from html.parser import HTMLParser
from pathlib import Path
import re
class Text(HTMLParser):
 hide=0
 def handle_starttag(self,tag,attrs):
  if tag in ('script','style'): self.hide+=1
 def handle_endtag(self,tag):
  if tag in ('script','style'): self.hide=max(0,self.hide-1)
 def handle_data(self,s):
  s=' '.join(s.split())
  if s and not self.hide and re.search(r'payout|withdraw|payment method|bank transfer|minimum balance|Canada|affiliate agreement|affiliate program terms',s,re.I): print(s[:800])
Text().feed(Path('products/distribution/invoice-referral-fit/raw/zoho.html').read_text())
